/**
 * Shared field and surface styles for the Base UI variant of Ink mail.
 *
 * These mirror `../components/_shared.ts`, so a Base UI component and its
 * Radix twin render the same field, the same floating panel and the same
 * off-white controls. Base UI marks state with bare attributes (data-checked,
 * data-highlighted, data-pressed, data-disabled), so the state selectors
 * differ from the Radix file.
 *
 * Ink mail fields are a dark card-step well behind a translucent white
 * hairline, with a 0.75rem corner. Focus brightens the edge to the off-white
 * ink and adds a faint white halo: no colour, the way the rest of the system
 * marks state with luminance.
 *
 * Do NOT copy-paste these classes into individual components - always import.
 */

/** Base styles shared by every form-field surface (Input, Textarea, etc.) */
export const formFieldBase =
  "w-full min-w-0 rounded-lg border border-(--line-strong) bg-(--field) px-3.5 text-sm text-foreground " +
  "placeholder:text-muted-foreground " +
  "transition-[border-color,box-shadow] duration-fast ease-out " +
  "hover:border-(--control) " +
  "focus-visible:border-foreground focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring " +
  "disabled:cursor-not-allowed disabled:bg-secondary disabled:text-(--foreground-disabled) disabled:placeholder:text-(--foreground-disabled) " +
  "data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled)";

/** Height + vertical padding for single-line form fields (2.5rem) */
export const formFieldSingleLine = "flex h-10 py-2";

/** Vertical padding and min-height for multi-line form fields */
export const formFieldMultiLine = "flex min-h-24 py-2.5";

/**
 * The floating panel shared by every menu, popover and dropdown: the
 * elevated surface step with a 0.75rem corner, edged by a translucent white
 * ring folded into a deep shadow token, so it lifts off the black page.
 */
export const popoverSurface =
  "rounded-lg bg-popover text-popover-foreground shadow-(--shadow-menu) outline-none";

/** Popups fade in and settle from their anchor, and leave a little faster. */
export const popupMotion =
  "origin-(--transform-origin) transition-[opacity,scale,translate] duration-fast ease-out " +
  "data-[starting-style]:scale-98 data-[starting-style]:opacity-0 " +
  "data-[ending-style]:scale-98 data-[ending-style]:opacity-0 data-[ending-style]:duration-fast";

/** The popover settles at the system's base duration, both ways. */
export const popoverMotion =
  "origin-(--transform-origin) transition-[opacity,scale,translate] duration-base ease-out " +
  "data-[starting-style]:scale-98 data-[starting-style]:opacity-0 " +
  "data-[ending-style]:scale-98 data-[ending-style]:opacity-0";

/** A highlighted row inside a floating panel: one step lighter, 0.5rem corner. */
export const menuItemBase =
  "relative flex min-h-8 cursor-default select-none items-center gap-2 rounded-md px-2.5 py-1.5 text-sm outline-none " +
  "transition-colors duration-fast " +
  "data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground " +
  "data-[disabled]:pointer-events-none data-[disabled]:text-(--foreground-disabled)";

/**
 * The primary fill: flat off-white with black ink, the brightest pixel on the
 * page. Hover dims it one step; the press turns it a cool blue-white.
 */
export const primaryFill =
  "bg-primary text-primary-foreground hover:bg-(--primary-hover) active:bg-(--primary-active)";

/**
 * The glass fill: a faint white gradient behind a translucent edge, for the
 * call to action that sits beside the solid one.
 */
export const glassFill =
  "border-2 border-(--glass-edge) bg-(image:--glass) text-foreground hover:bg-(image:--glass-hover)";

/**
 * The same off-white on a small checked control (checkbox, radio, switch
 * track). Base UI marks the checked state with data-checked. A disabled control
 * goes quiet even when checked.
 */
export const controlChecked =
  "data-[checked]:border-primary data-[checked]:bg-primary data-[checked]:text-primary-foreground " +
  "data-[disabled]:data-[checked]:border-(--line-strong) data-[disabled]:data-[checked]:bg-muted data-[disabled]:data-[checked]:text-(--foreground-disabled)";

/** A selected chip, toggle or nav row: a white wash at one tenth with full ink. */
export const activeWash =
  "data-[pressed]:bg-(--wash) data-[pressed]:text-foreground data-[pressed]:border-(--line-strong)";

/** The focus ring every interactive element uses: a faint white halo. */
export const focusRing =
  "outline-none focus-visible:ring-3 focus-visible:ring-ring";
